<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['refund15_csrf']))$_SESSION['refund15_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['refund15_csrf'];$error=null;$success=null;$sales=[];$returns=[];$refunds=[];$orderFilter=(int)($_GET['order']??0);
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'add');if($action==='add'){$returnRaw=trim((string)($_POST['return_id']??''));$id=sales_step15_add_refund($pdo,(int)$_POST['order_id'],$returnRaw===''?null:(int)$returnRaw,(string)$_POST['refund_date'],(float)$_POST['amount'],(string)$_POST['refund_method'],trim((string)($_POST['reference_no']??'')),trim((string)$_POST['reason']));$success='Customer Refund #'.$id.' recorded.';}elseif($action==='reverse'){sales_step15_reverse_refund($pdo,(int)$_POST['refund_id'],trim((string)$_POST['reason']));$success='Refund reversed with audit history.';}}$sales=sales_step15_sales_rows($pdo,$orgId);$stmt=$pdo->prepare("SELECT r.id,r.order_id,r.return_number,r.return_date,r.total_credit,COALESCE(x.refunded,0) refunded,(r.total_credit-COALESCE(x.refunded,0)) remaining_credit FROM sales_returns r LEFT JOIN (SELECT sales_return_id,SUM(amount) refunded FROM sales_refunds WHERE organization_id=? AND status='active' AND sales_return_id IS NOT NULL GROUP BY sales_return_id) x ON x.sales_return_id=r.id WHERE r.organization_id=? AND r.status='posted' ORDER BY r.return_date DESC,r.id DESC");$stmt->execute([$orgId,$orgId]);$returns=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT rf.*,COALESCE(c.customer_name,cl.customer_name_snapshot,q.customer_name,'Unlinked customer') customer_name,r.return_number FROM sales_refunds rf LEFT JOIN sales_customer_links cl ON cl.organization_id=rf.organization_id AND cl.order_id=rf.order_id LEFT JOIN crm_customers c ON c.id=cl.customer_id AND c.organization_id=rf.organization_id LEFT JOIN product_quote_order_links ql ON ql.organization_id=rf.organization_id AND ql.order_id=rf.order_id LEFT JOIN product_quotes q ON q.id=ql.quote_id AND q.organization_id=rf.organization_id LEFT JOIN sales_returns r ON r.id=rf.sales_return_id AND r.organization_id=rf.organization_id WHERE rf.organization_id=? ORDER BY rf.refund_date DESC,rf.id DESC");$stmt->execute([$orgId]);$refunds=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function rf_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function rf_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Customer Refunds - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="sales_fulfillment.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Customer Refunds</small></span></a><div class="os-top-actions"><a class="os-btn" href="sales_returns.php">Returns</a><a class="os-btn" href="sales_receivables.php">Receivables</a><a class="os-btn primary" href="sales_fulfillment.php">Fulfillment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">After-Sales</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a href="sales_invoice.php"><i class="dot"></i>Invoices</a><a href="sales_delivery.php"><i class="dot"></i>Delivery</a><a href="sales_returns.php"><i class="dot"></i>Returns</a><a class="active" href="sales_refunds.php"><i class="dot"></i>Refunds</a><a href="sales_receivables.php"><i class="dot"></i>Receivables</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 15F • CUSTOMER REFUNDS</div><h1>Refund customer money without rewriting payment history.</h1><p>Original payments remain preserved. Refunds are separate cash-out facts and may be reversed with audit history when entered incorrectly.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'REFUND CENTER LIVE':'Review required' ?></span><span class="os-chip"><?= count($refunds) ?> refund records</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Refund diagnostic:</strong> <?= rf_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= rf_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Record Customer Refund</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= rf_h($csrf) ?>"><input type="hidden" name="action" value="add"><label>Product Sale<select name="order_id" required><option value="">Choose sale with refundable payment…</option><?php foreach($sales as $s):$available=max(0,(float)$s['gross_collected']-(float)$s['refund_amount']);if($available<=0.009)continue;?><option value="<?= (int)$s['order_id'] ?>" <?= $orderFilter===(int)$s['order_id']?'selected':'' ?>>Order #<?= (int)$s['order_id'] ?> • <?= rf_h($s['customer_name']) ?> • Available <?= rf_m($available) ?></option><?php endforeach;?></select></label><label>Link Return Credit (optional)<select name="return_id"><option value="">General refund / no return link</option><?php foreach($returns as $r):if((float)$r['remaining_credit']<=0.009)continue;?><option value="<?= (int)$r['id'] ?>">Order #<?= (int)$r['order_id'] ?> • <?= rf_h($r['return_number']) ?> • Credit Remaining <?= rf_m($r['remaining_credit']) ?></option><?php endforeach;?></select></label><label>Refund Date<input type="date" name="refund_date" value="<?= rf_h(date('Y-m-d')) ?>" required></label><label>Amount<input type="number" min="0.01" step="0.01" name="amount" required></label><label>Method<select name="refund_method"><option value="upi">UPI</option><option value="bank">Bank</option><option value="cash">Cash</option><option value="card">Card</option><option value="other">Other</option></select></label><label>Reference<input name="reference_no"></label><label>Reason<textarea name="reason" minlength="5" rows="3" required></textarea></label><button>Record Refund →</button></form></article><article class="os-card pp-span-7"><h2>Refund History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Order / Customer</th><th>Return</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($refunds as $r):?><tr><td><?= rf_h($r['refund_date']) ?></td><td>Order #<?= (int)$r['order_id'] ?><small><?= rf_h($r['customer_name']) ?></small></td><td><?= rf_h($r['return_number']?:'—') ?></td><td><b><?= rf_m($r['amount']) ?></b></td><td><?= rf_h(strtoupper($r['refund_method'])) ?></td><td><?= rf_h($r['reference_no']?:'—') ?></td><td><?= rf_h(strtoupper($r['status'])) ?></td><td><?php if($r['status']==='active'):?><details><summary>Reverse</summary><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= rf_h($csrf) ?>"><input type="hidden" name="action" value="reverse"><input type="hidden" name="refund_id" value="<?= (int)$r['id'] ?>"><input name="reason" minlength="5" placeholder="Reversal reason" required><button>Reverse Refund</button></form></details><?php endif;?></td></tr><?php endforeach;?><?php if(!$refunds):?><tr><td colspan="8">No customer refunds yet.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?><div class="os-footer-note"><strong>Refund rule:</strong> active refunds can never exceed active customer payments; return-linked refunds also cannot exceed the remaining Credit Note amount.</div></main></div></body></html>